#!/usr/bin/env bash
# Writes frontend/js/config.js with the live Logic App trigger URLs.
# Used by deploy.sh and by the pipeline, so the signed URLs never sit in the repo.
set -euo pipefail
cd "$(dirname "$0")/.."
: "${RG:?set RG}"

SUB="$(az account show --query id -o tsv)"
url() {
  az rest --method post -o tsv --query value --uri \
    "https://management.azure.com/subscriptions/$SUB/resourceGroups/$RG/providers/Microsoft.Logic/workflows/la-claimsnap-$1/triggers/manual/listCallbackUrl?api-version=2016-06-01"
}

cat > frontend/js/config.js <<EOF
// Generated by scripts/write-config.sh on $(date -u +%Y-%m-%dT%H:%MZ). Do not commit.
export const endpoints = {
  iups: '$(url iups)',
  rai: '$(url rai)',
  rips: '$(url rips)',
  uips: '$(url uips)',
  dips: '$(url dips)',
};
EOF
echo "frontend/js/config.js written."
